(()=>{'use strict';
const M=window.ZooModel,$=s=>document.querySelector(s),canvas=$('#zoo-canvas'),ctx=canvas.getContext('2d');
let state=M.create(),tab='exhibit',undo=[],redo=[],buildStart=0,animationTime=0,lastFrame=0,elapsed=0,saved=false,pendingType=null;
const reduced=matchMedia('(prefers-reduced-motion:reduce)'),mobile=()=>innerWidth<=620;
const money=n=>(n<0?'−':'')+'$'+Math.abs(Math.round(n)).toLocaleString(),time=n=>`${Math.floor(n/60)%12||12}:${String(n%60).padStart(2,'0')} ${n<720?'AM':'PM'}`;
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(){return {...M.copy(state),metrics:M.metrics(M.copy(state)),storageScope:'this browser; explicit save',saved,canUndo:undo.length>0,canRedo:redo.length>0,renderReady:performance.now()-buildStart>850,view:{tab,controlsOpen:!document.body.classList.contains('tools-closed')},simulationScope:'Simplified capacity, comfort, visitor demand and cash flow. Flat accessible routes; no veterinary or ecological realism.'};}
function notify(message){$('#notice').textContent=message||'';}
function commit(action,args={}){const before=M.copy(state);const next=M.command(state,action,args);if(!['select','play','speed','advance'].includes(action)){undo.push(before);undo=undo.slice(-25);redo=[];}state=next;if(action==='select'||action==='swap')pendingType=null;if(state.lastBuild!==before.lastBuild)buildStart=performance.now();saved=false;renderUI();window.RanchView?.changed();return {affectedIds:args.tileId?[args.tileId]:state.tiles.map(t=>t.id),warnings:state.planner.warnings,state:read()};}
function history(direction){const src=direction==='undo'?undo:redo,dst=direction==='undo'?redo:undo;if(!src.length)throw Error('Nothing to '+direction);dst.push(M.copy(state));const rev=state.revision;state=src.pop();state.revision=rev+1;state.running=false;M.plan(state);buildStart=performance.now();saved=false;renderUI();window.RanchView?.changed();return read();}
function save(){localStorage.setItem('abbie-zoo-v1',JSON.stringify(state));saved=true;notify('Zoo saved on this browser.');window.RanchView?.changed();return {boardId:state.id,revision:state.revision,storageScope:'this-browser'};}
function load(){const raw=localStorage.getItem('abbie-zoo-v1');if(!raw)throw Error('No zoo saved in this browser yet');const next=M.restore(JSON.parse(raw));undo.push(M.copy(state));redo=[];next.revision=state.revision+1;state=next;saved=true;buildStart=performance.now();renderUI();notify('Saved zoo restored · paused');window.RanchView?.changed();return read();}
function safe(f){try{notify('');return f();}catch(e){notify(e.message);}}
function setTools(open){document.body.classList.toggle('tools-closed',!open);$('#tools-toggle').setAttribute('aria-expanded',String(open));$('#controls').inert=!open;window.RanchView?.changed();}
$('#tools-toggle').onclick=()=>setTools(document.body.classList.contains('tools-closed'));$('#tools-close').onclick=()=>setTools(false);
function setNav(open){$('#navigation').hidden=!open;$('#nav-toggle').setAttribute('aria-expanded',String(open));if(open)$('#nav-close').focus();}
$('#nav-toggle').onclick=()=>setNav($('#navigation').hidden);$('#nav-close').onclick=()=>setNav(false);
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#navigation').hidden){setNav(false);$('#nav-toggle').focus();}else{setTools(false);$('#tools-toggle').focus();}}});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderUI();window.RanchView?.changed();});
function stepper(t,key,label){return `<div class="field"><label>${label}</label><div class="stepper"><button aria-label="Decrease ${key}" data-setting="${key}" data-value="${t[key]-1}" ${t[key]===0?'disabled':''}>−</button><strong>${t[key]}</strong><button aria-label="Increase ${key}" data-setting="${key}" data-value="${t[key]+1}" ${t[key]===3?'disabled':''}>+</button></div></div>`;}
function renderUI(){const t=state.tiles[state.selected],d=M.types[t.type],m=M.metrics(state);$('#top-stats').innerHTML=`<div class="top-stat ${state.cash<100?'warning':''}"><small>FUNDS</small><strong>${money(state.cash)}</strong></div><div class="top-stat"><small>VISITORS</small><strong>${state.visitors}</strong></div><div class="top-stat"><small>ANIMAL COMFORT</small><strong>${Math.round(m.comfort)}%</strong></div><div class="top-stat"><small>DAY ${state.day}</small><strong>${time(state.minute)}</strong></div>`;
 $('#clock').textContent=time(state.minute);$('#event-count').textContent=state.event?' 1 ':'';$('#world-status').textContent=state.event?'A park decision is waiting · simulation paused':state.running?`${state.weather[0].toUpperCase()+state.weather.slice(1)} · life unfolding at ${state.speed}×`:'Paused · take your time';$('#build-status').textContent=`7 connected · ${state.planner.warnings.length?state.planner.warnings.length+' needs attention':'all needs covered'}`;
 document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.tab===tab)));$('#panel-title').textContent=tab==='exhibit'?'Exhibit studio':tab==='planner'?'Central planner':'Park decisions';
 let html='';if(tab==='exhibit'){html=`<span class="badge">HEX ${state.selected+1} / ${d.kind==='habitat'?'ECOSYSTEM':d.kind==='play'?'KID ZONE':'ADMINISTRATION'}</span><div class="species">${d.species||d.name}</div><span class="muted">${d.kind==='habitat'?d.name:'Park services'}</span>`;
 if(d.kind==='habitat')html+=`<div class="meter-row"><span>Animal comfort</span><strong>${Math.round(t.welfare)}%</strong></div><div class="meter"><i style="width:${t.welfare}%"></i></div>${stepper(t,'shade','Shade shelters')}${stepper(t,'enrichment','Enrichment stations')}<div class="field"><label for="quiet">Quiet viewing</label><input id="quiet" type="checkbox" ${t.quiet?'checked':''}></div>`;
 if(t.type==='care')html+=stepper(t,'staff','Keeper teams');
 html+=`<label class="section-label" for="tile-type">SWAP THIS TILE</label><select id="tile-type">${Object.entries(M.types).map(([id,v])=>`<option value="${id}" ${id===(pendingType||t.type)?'selected':''}>${v.name}</option>`).join('')}</select><button id="swap" class="primary" style="width:100%">Order tile swap ↗</button><div class="row"><button id="undo" ${!undo.length?'disabled':''}>↶ Undo</button><button id="redo" ${!redo.length?'disabled':''}>Redo ↷</button></div>`;
 }else if(tab==='planner'){html=`<span class="badge">AUTOMATIC · CONNECT / REBUILD / CHECK</span><div class="planner-grid"><div><strong>7 / 7</strong><span>Connected & step-free</span></div><div><strong>${state.planner.care} / ${state.planner.demand}</strong><span>Keeper capacity / need</span></div><div><strong>${state.planner.food}</strong><span>Food service capacity</span></div><div><strong>${money(m.income-m.expense)}</strong><span>Net / simulation step</span></div></div><div class="row"><button id="play" class="primary" ${state.event?'disabled':''}>${state.running?'Ⅱ Pause':'▶ Run'}</button><button id="advance" ${state.event?'disabled':''}>Step 5 min</button></div><label class="section-label" for="speed">SIMULATION SPEED</label><select id="speed">${[1,2,4].map(n=>`<option value="${n}" ${state.speed===n?'selected':''}>${n}×</option>`).join('')}</select><button id="replan" style="width:100%">Rebuild park connections</button>${state.planner.warnings.map(w=>`<div class="warning-box">${escape(w.message)}</div>`).join('')}<div class="row"><button id="save">Save zoo</button><button id="load">Load zoo</button></div><div class="row"><button id="export">Export</button><button id="fit">Fit view</button></div><span class="muted">Browser-local save · flat toy simulation</span>`;
 }else{html=state.event?`<div class="choice"><span class="badge">YOUR DECISION</span><h3>${state.event.title}</h3><p>${state.event.body}</p>${state.event.choices.map(c=>`<button data-choice="${c.id}">${c.label}<small>${c.effect}</small></button>`).join('')}</div>`:'<div class="empty-choice">The zoo is ticking along.<br>No decision waiting.</div>';html+=`<span class="section-label">TRY A SCENARIO</span><div class="row"><button data-scenario="heat" ${state.event?'disabled':''}>Hot afternoon</button><button data-scenario="school" ${state.event?'disabled':''}>School visit</button></div>`;}
 const focus=document.activeElement?.getAttribute('aria-label')||document.activeElement?.id;$('#panel-content').innerHTML=html;
 $('#panel-content').querySelectorAll('[data-setting]').forEach(b=>b.onclick=()=>safe(()=>commit('configure',{tileId:t.id,key:b.dataset.setting,value:Number(b.dataset.value)})));
 if($('#quiet'))$('#quiet').onchange=e=>safe(()=>commit('configure',{tileId:t.id,key:'quiet',value:e.target.checked}));
 if($('#tile-type'))$('#tile-type').onchange=e=>pendingType=e.target.value;
 if($('#swap'))$('#swap').onclick=()=>safe(()=>commit('swap',{tileId:t.id,type:$('#tile-type').value}));
 const bind=(id,f)=>{if($(id))$(id).onclick=()=>safe(f);};bind('#undo',()=>history('undo'));bind('#redo',()=>history('redo'));bind('#play',()=>commit('play',{running:!state.running}));bind('#advance',()=>commit('advance',{steps:1}));bind('#replan',()=>commit('replan'));bind('#save',save);bind('#load',load);bind('#fit',()=>{draw();notify('All seven hexes in view.');});bind('#export',()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='abbies-zoo.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});if($('#speed'))$('#speed').onchange=e=>safe(()=>commit('speed',{value:Number(e.target.value)}));
 $('#panel-content').querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>safe(()=>commit('resolve',{choice:b.dataset.choice})));$('#panel-content').querySelectorAll('[data-scenario]').forEach(b=>b.onclick=()=>safe(()=>commit('scenario',{kind:b.dataset.scenario})));
 if(focus){const el=[...$('#panel-content').querySelectorAll('button,input,select')].find(e=>e.id===focus||e.getAttribute('aria-label')===focus);el?.focus({preventScroll:true});}
 $('#event-log').innerHTML=state.log.map(e=>`<li class="${e.kind==='choice'?'choice-log':''}"><time>DAY ${e.day} · ${time(e.minute)} / ${e.kind.toUpperCase()}</time>${escape(e.message)}</li>`).join('');
 $('#tile-targets').innerHTML=state.tiles.map((t,i)=>`<button class="tile-target" data-tile="${t.id}" aria-label="Select ${M.types[t.type].name}, hex ${i+1}" aria-pressed="${state.selected===i}">${M.types[t.type].name}</button>`).join('');$('#tile-targets').querySelectorAll('button').forEach(b=>b.onclick=()=>{safe(()=>commit('select',{tileId:b.dataset.tile}));tab='exhibit';setTools(true);renderUI();});draw();}
// A shared flat visitor corridor surrounds each fenced habitat. All seven
// perimeters touch at the same height; decorative objects stay inside the fence.
const centers=M.cells.map(([q,r])=>({x:Math.sqrt(3)*100*(q+r/2),y:150*r}));
let W=0,H=0,scale=1,origin={x:0,y:0};
function point(x,y,z=0){return {x:origin.x+x*scale,y:origin.y+(y*.7-z)*scale};}
function poly(points,fill,stroke,width=1){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=width;ctx.stroke();}}
function ellipse(x,y,rx,ry,fill){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();}
function hex(c,r,z=0){return Array.from({length:6},(_,i)=>{const a=(i*60-30)*Math.PI/180;return point(c.x+Math.cos(a)*r,c.y+Math.sin(a)*r,z);});}
function box(x,y,w,d,h,color,roof){const a=point(x-w/2,y-d/2),b=point(x+w/2,y-d/2),c=point(x+w/2,y+d/2),e=point(x-w/2,y+d/2);const up=p=>({x:p.x,y:p.y-h*scale});poly([a,b,up(b),up(a)],color);poly([b,c,up(c),up(b)],'#87937a');poly([c,e,up(e),up(c)],color);poly([up(a),up(b),up(c),up(e)],roof||color,'#40513b25',.7);}
function line(a,b,color,width){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.lineCap='round';ctx.stroke();}
function tree(x,y,size=1,z=0){const p=point(x,y,z);ellipse(p.x+5*scale,p.y+3*scale,12*size*scale,5*size*scale,'#38503d13');line(p,{x:p.x,y:p.y-26*size*scale},'#8c7955',4*size*scale);ellipse(p.x,p.y-31*size*scale,15*size*scale,17*size*scale,'#65876a');ellipse(p.x-5*size*scale,p.y-36*size*scale,10*size*scale,11*size*scale,'#90aa78');}
function building(c,type,lift){const p=point(c.x,c.y,lift);ctx.save();ctx.translate(0,-lift*scale);box(c.x,c.y,55,38,30,type==='care'?'#e9e6cb':'#e7c99a','#527c6b');const door=point(c.x,c.y+20,0);ctx.fillStyle='#617568';ctx.fillRect(door.x-5*scale,door.y-19*scale,10*scale,19*scale);for(const dx of [-17,17]){const w=point(c.x+dx,c.y+20,21);ctx.fillStyle='#f9efc8';ctx.fillRect(w.x-4*scale,w.y,8*scale,8*scale);}if(type==='care'){ctx.fillStyle='#ecf1dc';ctx.fillRect(p.x-8*scale,p.y-41*scale,16*scale,5*scale);ctx.fillRect(p.x-2.5*scale,p.y-46*scale,5*scale,16*scale);}if(type==='cafe'){for(const dx of [-37,37]){const u=point(c.x+dx,c.y+22,15);line(point(c.x+dx,c.y+22),u,'#8a785c',2*scale);ellipse(u.x,u.y,13*scale,6*scale,'#dc966a');}}ctx.restore();}
function animal(x,y,type,id,lift){const motion=state.running&&!reduced.matches?animationTime:0;const bob=Math.sin(motion*4+id)*1.5;const p=point(x,y,lift+bob);const s=scale;ellipse(p.x,p.y+3*s,9*s,4*s,'#3e50351c');ctx.save();ctx.translate(p.x,p.y);const color=type==='savanna'?'#d8a252':type==='wetlands'?'#e9a5a0':type==='rainforest'?'#696e66':type==='woodland'?'#b86e42':'#e8e1cb';
 for(const dx of [-6,5]){ctx.fillStyle='#71644f';ctx.fillRect(dx*s,-5*s,3*s,10*s);}ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(-10*s,-15*s,22*s,13*s,4*s);ctx.fill();if(type==='savanna'){ctx.fillRect(7*s,-36*s,6*s,26*s);ctx.fillRect(7*s,-39*s,13*s,8*s);ctx.fillStyle='#ac7838';for(const [a,b]of [[-5,-13],[2,-9],[9,-25]])ctx.fillRect(a*s,b*s,4*s,4*s);}else if(type==='wetlands'){line({x:7*s,y:-9*s},{x:10*s,y:-29*s},color,4*s);ellipse(12*s,-29*s,5*s,4*s,color);}else{ellipse(10*s,-17*s,8*s,7*s,color);ellipse(7*s,-23*s,3*s,4*s,color);ellipse(14*s,-23*s,3*s,4*s,color);if(type==='rainforest'||type==='woodland')line({x:-9*s,y:-12*s},{x:-17*s,y:-28*s},color,5*s);}
 ctx.fillStyle='#2c3c31';ctx.fillRect((type==='savanna'?16:13)*s,(type==='savanna'?-37:type==='wetlands'?-31:-19)*s,2*s,2*s);ctx.restore();}
function draw(){const bounds=canvas.getBoundingClientRect();W=bounds.width;H=bounds.height;if(!W||!H)return;const ratio=Math.min(devicePixelRatio,2);if(canvas.width!==Math.round(W*ratio)||canvas.height!==Math.round(H*ratio)){canvas.width=Math.round(W*ratio);canvas.height=Math.round(H*ratio);}ctx.setTransform(ratio,0,0,ratio,0,0);ctx.clearRect(0,0,W,H);scale=Math.min((W-45)/540,(H-170)/405,1.65);scale=Math.max(.25,scale);origin={x:W*.5,y:H*.53+22};const age=(performance.now()-buildStart)/1000;const lift=!reduced.matches&&age<.85?Math.max(0,Math.cos(age*12)*Math.exp(-age*4)*24):0;
 const ordered=centers.map((c,i)=>({...c,i})).sort((a,b)=>a.y-b.y);for(const c of ordered){const top=hex(c,98,0),bottom=hex(c,98,-13);poly(bottom,'#7e9672');for(let j=0;j<6;j++){const k=(j+1)%6;if(top[j].y>origin.y+c.y*.7*scale-1||top[k].y>origin.y+c.y*.7*scale-1)poly([top[j],top[k],bottom[k],bottom[j]],'#9eae88');}poly(top,M.types[state.tiles[c.i].type].color,'#f5f2d8',3*scale);}
 // One continuous shared path ribbon along cell boundaries, outside enclosures.
 for(const e of state.planner.edges)line(point(e.from.x,e.from.y),point(e.to.x,e.to.y),'#f3e7c5',10*scale);
 for(const c of ordered){poly(hex(c,87),null,'#f3e7c5',10*scale);if(c.i===state.selected)poly(hex(c,98),null,'#426c50',2.5*scale);}
 for(const c of ordered){const t=state.tiles[c.i],d=M.types[t.type];if(d.kind==='habitat'){poly(hex(c,72),d.color,'#84916b',1*scale);for(let j=0;j<6;j++){const a=(j*60-30)*Math.PI/180,p=point(c.x+Math.cos(a)*72,c.y+Math.sin(a)*72);line(p,{x:p.x,y:p.y-9*scale},'#e6d6aa',2*scale);}if(t.type==='wetlands'){const p=point(c.x-5,c.y+10);ellipse(p.x,p.y,43*scale,20*scale,'#77aeb0');ellipse(p.x-8*scale,p.y-3*scale,27*scale,9*scale,'#a4ced0');}if(t.type==='highlands'){box(c.x-25,c.y-20,30,25,20,'#919d96','#c2c7b7');box(c.x-10,c.y-30,23,20,32,'#9aa79b','#d2d3c1');}
 for(let j=0;j<t.shade+1;j++)tree(c.x-38+j*23,c.y-38, t.type==='rainforest'?1.2:.85,lift);for(let j=0;j<t.enrichment;j++){box(c.x-34+j*24,c.y+32,12,10,8,'#bb895c','#dcc68d');}
 const motion=state.running&&!reduced.matches?animationTime:0;for(let j=0;j<3;j++){let x=c.x-20+j*22+Math.sin(motion*.35+j*2+c.i)*10,y=c.y+Math.cos(motion*.4+j*2)*10;if(t.welfare<65||state.weather==='hot')y-=18;animal(x,y,t.type,j+c.i,lift);}if(t.quiet){const p=point(c.x+48,c.y-7,lift);ellipse(p.x,p.y-8*scale,9*scale,9*scale,'#eef1da');ctx.fillStyle='#477259';ctx.font=`${11*scale}px sans-serif`;ctx.textAlign='center';ctx.fillText('♡',p.x,p.y-4*scale);}
 }else if(d.kind==='admin'){building(c,t.type,lift);tree(c.x-47,c.y-28,.75,lift);tree(c.x+43,c.y-30,.9,lift);}else if(t.type==='adventure'){ctx.save();ctx.translate(0,-lift*scale);box(c.x-13,c.y-6,30,26,32,'#d5a16e','#6a9c9a');line(point(c.x+3,c.y,30),point(c.x+35,c.y+23,0),'#db8060',10*scale);for(let j=0;j<3;j++)box(c.x-40+j*14,c.y+30,10,10,6+j*3,'#8da69e','#c6d8b6');ctx.restore();tree(c.x+35,c.y-35,.8,lift);}else{for(let j=0;j<3;j++){const p=point(c.x-30+j*30,c.y+5,lift);ellipse(p.x,p.y,12*scale,8*scale,['#e7bc6b','#d9a2a0','#b1c59e'][j]);}tree(c.x,c.y-35,1.1,lift);}
 }
 // Visitors follow the perimeter edges used by the planner, never through pens.
 const motion=state.running&&!reduced.matches?animationTime:0;for(let i=0;i<Math.min(35,Math.ceil(state.visitors/2));i++){const c=centers[i%7],travel=(motion*.12+i*.83)%6,side=Math.floor(travel),f=travel-side,a=(side*60-30)*Math.PI/180,b=((side+1)*60-30)*Math.PI/180;const p=point(c.x+(Math.cos(a)*(1-f)+Math.cos(b)*f)*87,c.y+(Math.sin(a)*(1-f)+Math.sin(b)*f)*87);ellipse(p.x,p.y,3*scale,2*scale,'#51604420');ctx.fillStyle=['#bf715c','#507b82','#c6a354','#6c796a'][i%4];ctx.beginPath();ctx.roundRect(p.x-2.5*scale,p.y-9*scale,5*scale,7*scale,2*scale);ctx.fill();ellipse(p.x,p.y-11*scale,2.8*scale,2.8*scale,'#e9ccaa');}
 const buttons=$('#tile-targets').children;for(let i=0;i<7;i++){if(!buttons[i])continue;const p=point(centers[i].x,centers[i].y+59);buttons[i].style.left=p.x+'px';buttons[i].style.top=p.y+'px';}
 $('#build-status').textContent=lift>1?'Planner rebuilding · pieces snapping into place':`7 connected · ${state.planner.warnings.length?state.planner.warnings.length+' needs attention':'all needs covered'}`;}
function frame(now){const dt=Math.min((now-lastFrame)/1000,.1);lastFrame=now;if(!document.hidden){if(state.running){animationTime+=dt;elapsed+=dt*state.speed;if(elapsed>=4){elapsed=0;const before=!!state.event;M.advance(state);if(state.event&&!before)tab='events';renderUI();window.RanchView?.changed();}}draw();}requestAnimationFrame(frame);}
const schema=properties=>({type:'object',properties,required:Object.keys(properties)}),str={type:'string'},tileId={type:'string',enum:state.tiles.map(t=>t.id)};
const defs={inspect:{description:'Inspect zoo, planner warnings, economy, animals, events and revisions',readOnly:true,schema:schema({}),run:read},select:{description:'Select a zoo tile',schema:schema({tileId}),run:a=>commit('select',a)},play:{description:'Run or pause the simulation; pending choices require resolution',schema:schema({running:{type:'boolean'}}),run:a=>commit('play',a)},speed:{description:'Set simulation playback speed',schema:schema({value:{type:'integer',enum:[1,2,4]}}),run:a=>commit('speed',a)},advance:{description:'Advance 1–12 five-minute steps; stops at a choice',schema:schema({steps:{type:'integer',minimum:1,maximum:12}}),run:a=>commit('advance',a)},swap:{description:'Replace a tile and rebuild connected paths',schema:schema({tileId,type:{type:'string',enum:Object.keys(M.types)}}),run:a=>commit('swap',a)},configure:{description:'Set exhibit shade/enrichment or care staffing, 0–3',schema:schema({tileId,key:{type:'string',enum:['shade','enrichment','staff']},value:{type:'integer',minimum:0,maximum:3}}),run:a=>commit('configure',a)},quiet:{description:'Toggle quiet viewing for an animal habitat',schema:schema({tileId,value:{type:'boolean'}}),run:a=>commit('configure',{...a,key:'quiet'})},resolve:{description:'Resolve a currently offered park decision by choice ID',schema:schema({choice:str}),run:a=>commit('resolve',a)},scenario:{description:'Start a hot-afternoon or school-visit scenario',schema:schema({kind:{type:'string',enum:['heat','school']}}),run:a=>commit('scenario',a)},replan:{description:'Rebuild paths and inspect service needs',schema:schema({}),run:()=>commit('replan')},save:{description:'Save zoo to this browser',schema:schema({}),run:save},load:{description:'Restore this browser’s saved zoo, paused',schema:schema({}),run:load},undo:{description:'Undo the last committed configuration or decision; pauses simulation',schema:schema({}),run:()=>history('undo')},redo:{description:'Redo a configuration edit; pauses simulation',schema:schema({}),run:()=>history('redo')},export:{description:'Return structured zoo artifact',schema:schema({}),readOnly:true,run:()=>M.copy(state)}};
window.RanchView?.register('zoo',read,draw);window.RanchActions?.register('zoo',{revision:()=>state.revision,read,actions:defs,unavailable:action=>action==='undo'&&!undo.length?'No edit to undo':action==='redo'&&!redo.length?'No edit to redo':null});
const sharedButtons=new MutationObserver(()=>{for(const id of ['app-jukebox-toggle','app-settings-toggle']){const b=document.getElementById(id);if(b&&b.parentElement!==document.querySelector('#controls .drawer-heading'))document.querySelector('#controls .drawer-heading').insertBefore(b,document.getElementById('tools-close'));}});sharedButtons.observe(document.body,{childList:true});
setTools(!mobile());renderUI();new ResizeObserver(draw).observe($('#world'));requestAnimationFrame(frame);
})();
